using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Animations;using UnityEngine.Playables;
namespace Game.Editor.Barrack { public static class GrozaPersistenceProbe {
public static void Run(){var old=Shader.globalRenderPipeline;Shader.globalRenderPipeline="UniversalPipeline";GameObject model=null;var log="";AssetBundle shaderBundle=null;AssetBundle animationBundle=null;PlayableGraph graph=default;try{
var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Game/Content/BarrackSource/GrozaSR01/GrozaSR01.prefab");if(prefab==null)throw new Exception("Prefab missing");model=UnityEngine.Object.Instantiate(prefab);model.SetActive(true);
animationBundle=AssetBundle.LoadFromMemory(File.ReadAllBytes("Assets/Game/Content/BarrackSource/GrozaSR01/OriginalBarrackAnimations.bytes"));var clip=animationBundle.LoadAllAssets<AnimationClip>().Single(c=>c.name=="c_GrozaSR01_BarrackIdle");log+="original clip length="+clip.length+" human="+clip.humanMotion+" empty="+clip.empty+"\n";var animator=model.GetComponentInChildren<Animator>();animator.enabled=true;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();graph=PlayableGraph.Create("GrozaPoseProbe");graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var animation=AnimationClipPlayable.Create(graph,clip);animation.SetTime(0.25);var output=AnimationPlayableOutput.Create(graph,"Pose",animator);output.SetSourcePlayable(animation);graph.Play();graph.Evaluate(0);
shaderBundle=AssetBundle.LoadFromMemory(File.ReadAllBytes("Assets/Game/Content/BarrackSource/GrozaSR01/OriginalCharacterShaders.bytes"));var shaders=shaderBundle.LoadAllAssets<Shader>();
var rr=model.GetComponentsInChildren<SkinnedMeshRenderer>(true);foreach(var renderer in rr){renderer.sharedMaterials=renderer.sharedMaterials.Select(material=>new Material(material){shader=shaders.Single(s=>s.name==material.shader.name)}).ToArray();}
foreach(var r in rr){if(r.sharedMesh==null||r.bones.Any(b=>b==null))throw new Exception("Mesh/bones missing");foreach(var m in r.sharedMaterials){if(m==null||m.shader==null||m.FindPass("GFCharForward")<0)throw new Exception("Shader pass missing");foreach(var prop in m.GetTexturePropertyNames()){var t=m.GetTexture(prop);if(t!=null&&!EditorUtility.IsPersistent(t))throw new Exception("Transient texture");}log+=m.name+" shader="+m.shader.name+" supported="+m.shader.isSupported+" base="+(m.GetTexture("_BaseMap")?.name??"none")+"\n";}}
var bounds=rr[0].bounds;foreach(var r in rr)bounds.Encapsulate(r.bounds);log+="bounds="+bounds+"\n";

var cameraObject=new GameObject("SourceMaterialDiagnosticCamera");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.transform.position=bounds.center+Vector3.back*3;camera.transform.LookAt(bounds.center);camera.fieldOfView=40;camera.aspect=0.75f;camera.nearClipPlane=0.05f;camera.farClipPlane=20;
var rt=new RenderTexture(768,1024,24,RenderTextureFormat.ARGBHalf);rt.Create();var command=new CommandBuffer();var baked=new System.Collections.Generic.List<Mesh>();
try{command.SetRenderTarget(rt);command.ClearRenderTarget(true,true,new Color(0.12f,0.14f,0.18f,1));command.SetViewProjectionMatrices(camera.worldToCameraMatrix,GL.GetGPUProjectionMatrix(camera.projectionMatrix,true));command.SetGlobalVector("_WorldSpaceCameraPos",camera.transform.position);command.SetGlobalVector("_MainLightPosition",-(new Quaternion(-0.2951809764f,0.1819778681f,-0.0573773943f,-0.9361944795f)*Vector3.forward));command.SetGlobalVector("_MainLightColor",new Vector4(1.3f,1.229f,1.131f,1));command.SetGlobalVector("unity_LightData",new Vector4(0,0,1,0));command.SetGlobalVector("unity_SHAr",new Vector4(0,0,0,0.2f));command.SetGlobalVector("unity_SHAg",new Vector4(0,0,0,0.2f));command.SetGlobalVector("unity_SHAb",new Vector4(0,0,0,0.2f));
foreach(var r in rr){var mesh=new Mesh();r.BakeMesh(mesh);baked.Add(mesh);for(int i=0;i<r.sharedMaterials.Length;i++){var m=r.sharedMaterials[i];var pass=m.FindPass("GFCharForward");command.DrawMesh(mesh,r.localToWorldMatrix,m,i,pass);}}
Graphics.ExecuteCommandBuffer(command);var oldTarget=RenderTexture.active;RenderTexture.active=rt;var pixels=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);pixels.Apply();if(pixels.GetPixels32().Select(c=>((int)c.r<<16)|((int)c.g<<8)|c.b).Distinct().Count()<100)throw new Exception("Draw output is empty or uniform");var colors=pixels.GetPixels32();for(int y=0;y<pixels.height/2;y++)for(int x=0;x<pixels.width;x++){int a=y*pixels.width+x,b=(pixels.height-1-y)*pixels.width+x;var temp=colors[a];colors[a]=colors[b];colors[b]=temp;}pixels.SetPixels32(colors);pixels.Apply();File.WriteAllBytes(Path.ChangeExtension(Environment.GetEnvironmentVariable("GF2_PROBE_REPORT"),"png"),pixels.EncodeToPNG());RenderTexture.active=oldTarget;UnityEngine.Object.DestroyImmediate(pixels);
}finally{foreach(var mesh in baked)UnityEngine.Object.DestroyImmediate(mesh);command.Release();rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(cameraObject);}

File.WriteAllText(Environment.GetEnvironmentVariable("GF2_PROBE_REPORT"),"SOURCE_RESOURCE_DRAW_DIAGNOSTIC_NOT_FINAL_RENDERING\n"+log);
}catch(Exception ex){File.WriteAllText(Environment.GetEnvironmentVariable("GF2_PROBE_REPORT"),"FAIL\n"+ex);throw;}finally{if(model!=null)foreach(var m in model.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct())if(!EditorUtility.IsPersistent(m))UnityEngine.Object.DestroyImmediate(m);if(graph.IsValid())graph.Destroy();if(model!=null)UnityEngine.Object.DestroyImmediate(model);if(animationBundle!=null)animationBundle.Unload(true);if(shaderBundle!=null)shaderBundle.Unload(true);Shader.globalRenderPipeline=old;}
}}}
